<template><q-dialog v-model="visible"><q-card class="detail-card"><q-card-section class="row justify-between items-center bg-green-8 text-white"><div><div class="text-h6 text-weight-bold">Detalle de existencia</div><div class="text-caption">{{ item?.codigo }}</div></div><q-btn flat round icon="close" v-close-popup/></q-card-section><q-card-section v-if="item"><div class="text-subtitle1 text-weight-bold text-green-9">{{item.nombre}}</div><div class="text-caption text-grey-7">{{item.categoria}} · {{item.unidadBase}}</div><div class="row q-col-gutter-md q-mt-md"><div v-for="d in details" :key="d.label" class="col-6 col-sm-3"><div class="detail-label">{{d.label}}</div><div class="text-weight-bold">{{d.value}}</div></div></div><q-separator class="q-my-md"/><div class="text-subtitle2 text-weight-bold q-mb-sm">Distribución por lote</div><q-list v-if="item.lotes?.length" bordered separator><q-item v-for="l in item.lotes" :key="l.idLote"><q-item-section><q-item-label>{{l.codigoLote}}</q-item-label><q-item-label caption>{{l.almacen}} · {{l.ubicacion}} · vence {{l.fechaVencimiento}}</q-item-label></q-item-section><q-item-section side class="text-weight-bold">{{l.cantidad}} {{item.unidadBase}}</q-item-section></q-item></q-list><div v-else class="text-grey-6 text-caption">No hay lotes asociados.</div></q-card-section><q-card-actions align="right"><q-btn flat label="Cerrar" color="green-8" v-close-popup/><q-btn unelevated label="Ver Kardex" color="green-8" @click="emit('kardex',item)"/></q-card-actions></q-card></q-dialog></template>
<script setup>
import { computed, ref, watch } from 'vue'
import { obtenerDetalleExistencia } from '../../api/inventario/inventario'
const props=defineProps({modelValue:Boolean,item:Object});const emit=defineEmits(['update:modelValue','kardex']);const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)});const cargado=ref(null);const item=computed(()=>cargado.value||props.item);const details=computed(()=>item.value?[{label:'Stock total',value:item.value.stockActual??item.value.cantidad},{label:'Stock mínimo',value:item.value.stockMinimo},{label:'Stock máximo',value:item.value.stockMaximo},{label:'Estado',value:item.value.estado},{label:'Almacén',value:item.value.almacen},{label:'Ubicación',value:item.value.ubicacion}]:[]);watch(()=>[props.modelValue,props.item?.idExistencia],async([abierto])=>{if(abierto&&props.item?.idExistencia){cargado.value=await obtenerDetalleExistencia(props.item.idExistencia)}},{immediate:true})
</script>
<style scoped>.detail-card{width:760px;max-width:95vw;border-radius:18px}.detail-label{font-size:11px;color:#7c8b78;text-transform:uppercase;font-weight:800}</style>
